// Generated by Claude - Opus 5.5
// Checks the mod against the engine's own rules: run `claude plugin test .`
import { expect, test } from 'claude-code/testing'

import { SOUND } from './register'

// Stand in for the app: answer every call the mod makes at session start.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const app = (on: (event: any, hook: (...args: any[]) => unknown) => void, log: string[], played: string[]) => {
  on('session.start', (_, e) => ({ cwd: e.cwd }))
  on('theme.set', (_, e) => { log.push((e as { sound?: unknown }).sound ? 'theme+sound' : 'theme'); return { value: { isDrawn: true, requestId: 'backdrop' } } })
  on('ui.log', (_, e) => { log.push(`log: ${(e as { text: string }).text}`); return { value: undefined } })
  on('ui.toast', () => ({ value: undefined }))
  on('ui.invalidate', () => ({ value: undefined }))
  on('store.get', () => ({ value: undefined }))
  on('command.register', () => ({ value: { command: 'pond' } }))
  on('session.usage', () => ({ value: { startedAt: 0, context: { window: 200000, percent: 10 }, rateLimits: [] } }))
  on('clock.now', () => ({ value: 1_700_000_000_000 }))
  on('clock.after', () => ({ value: undefined }))
  on('audio.play', (_, e) => { played.push((e as { clip: { asset: string } }).clip.asset); return { value: undefined } })
}

test('the theme is sent with its sound, and the engine accepts it', async ($, on) => {
  const log: string[] = [], played: string[] = []
  app(on, log, played)
  await $.session.start({ cwd: '/', surface: 'desktop', isInteractive: true })
  expect(log).toEqual(['theme+sound']) // a refused sound would add a log line and a second set
  // (the song starts on a timer, which the test clock never reaches)
})


// The desktop app refuses the WHOLE theme sound if any layer lasts over 4 s,
// and the test kit above does not check that. Measured as the app reported:
// (notes - 1) x step + attack + release.
test('every sound layer fits the app\'s 4-second limit', async () => {

  const layers = [...(SOUND?.ambience?.layers ?? []), ...Object.values(SOUND?.cues ?? {}).flatMap(cue => cue?.layers ?? [])]
  for (const layer of layers) {
    if ('drone' in layer || !('notes' in layer)) continue // a drone plays on and is not measured
    const seconds = (layer.notes.length - 1) * (layer.step ?? 0) + (layer.attack ?? 0.005) + (layer.release ?? 0.4)
    expect(seconds <= 4).toBe(true)
  }
})
